package muxd

import (
	"encoding/base64"
	"encoding/json"
	"fmt"
	"os"
	"strings"
	"testing"
)

// The terminal model's contract is "indistinguishable from the browser's terminal" — xterm.js
// 6.0.0, the frontend's version. testdata/xterm_reflow_vectors.json holds random streams and
// resizes together with the state xterm itself ended in (generated by running them through
// @xterm/headless; the generator is scripts/diag/xtermvectors). This replays each through
// NewTerminalModel and compares what a person would see: every screen row's text and wrap flag,
// the cursor, which screen is up, the parked normal screen, and the scrollback.

type xtermVector struct {
	Name string `json:"name"`
	Cols int    `json:"cols"`
	Rows int    `json:"rows"`
	Ops  []struct {
		W      string `json:"w"`
		Resize []int  `json:"resize"`
	} `json:"ops"`
	Expect struct {
		Alt          bool        `json:"alt"`
		Cursor       [2]int      `json:"cursor"`
		Screen       []xtermLine `json:"screen"`
		NormalScreen []xtermLine `json:"normalScreen"`
		Scrollback   []xtermLine `json:"scrollback"`
	} `json:"expect"`
}

type xtermLine struct {
	T string `json:"t"`
	W bool   `json:"w"`
}

// modelLines renders lines the way xterm's translateToString(true) does: up to the last cell
// with content — written spaces included, erased (null) cells not. A zero-width character in the
// text is stacked on the cell before it unless the line says (Lone) that it stands in a cell of its
// own, which takes a column; a row is cut where its next cell would start at or past the content.
func modelLines(lines []Line) []xtermLine {
	out := make([]xtermLine, len(lines))
	for i, ln := range lines {
		var b strings.Builder
		col := 0
		lone, hidden := ln.Lone, ln.Hidden
	text:
		for _, r := range ln.Text {
			w := runeWidth(r)
			for len(hidden) > 0 && int(hidden[0].Col) <= col {
				hidden = hidden[1:]
			}
			if w == 1 && len(hidden) > 0 && int(hidden[0].Col) == col+1 {
				w = 2 // a cell kept behind a narrow character: a mark widened it (see extWide)
			}
			if w == 0 {
				for len(lone) > 0 && int(lone[0]) < col {
					lone = lone[1:]
				}
				if len(lone) > 0 && int(lone[0]) == col {
					if col >= ln.Content {
						break text
					}
					b.WriteRune(r)
					col++ // no width, but the cursor moved past it
					if len(hidden) > 0 && int(hidden[0].Col) == col {
						col++ // unless a mark widened it
					}
				} else {
					b.WriteRune(r) // stacked on the cell just written
				}
				continue
			}
			if col >= ln.Content {
				break
			}
			b.WriteRune(r)
			col += w
		}
		for ; col < ln.Content; col++ {
			b.WriteByte(' ')
		}
		out[i] = xtermLine{T: b.String(), W: ln.Wrapped}
	}
	return out
}

func firstLineDiff(what string, want, got []xtermLine) string {
	if len(want) != len(got) {
		return fmt.Sprintf("%s: %d rows, want %d", what, len(got), len(want))
	}
	for i := range want {
		if want[i] != got[i] {
			return fmt.Sprintf("%s row %d: got %q wrapped=%v, want %q wrapped=%v", what, i, got[i].T, got[i].W, want[i].T, want[i].W)
		}
	}
	return ""
}

func TestTerminalModel_MatchesXtermThroughRandomStreamsAndResizes(t *testing.T) {
	file := "testdata/xterm_reflow_vectors.json"
	if f := os.Getenv("XTERM_VECTORS"); f != "" {
		file = f // a one-off set, e.g. without resizes while chasing a base-semantics divergence
	}
	data, err := os.ReadFile(file)
	if err != nil {
		t.Fatalf("read vectors: %v", err)
	}
	var vectors []xtermVector
	if err := json.Unmarshal(data, &vectors); err != nil {
		t.Fatalf("parse vectors: %v", err)
	}
	failed := 0
	for _, v := range vectors {
		h := NewTerminalModel(Grid{Cols: v.Cols, Rows: v.Rows}, 100_000)
		for _, op := range v.Ops {
			if len(op.Resize) == 2 {
				h.Resize(Grid{Cols: op.Resize[0], Rows: op.Resize[1]})
				continue
			}
			b, _ := base64.StdEncoding.DecodeString(op.W)
			h.Write(b)
		}
		st, scroll, ok := h.State(100_000)
		if !ok {
			// A panic in the model is a divergence like any other; keep counting so one broken
			// vector does not hide how many more there are.
			failed++
			if failed <= 8 {
				t.Errorf("%s: model broke: %+v", v.Name, h.Stats())
			}
			continue
		}
		var diffs []string
		if st.Alt != v.Expect.Alt {
			diffs = append(diffs, fmt.Sprintf("alt=%v want %v", st.Alt, v.Expect.Alt))
		}
		if [2]int{st.CursorCol, st.CursorRow} != v.Expect.Cursor {
			diffs = append(diffs, fmt.Sprintf("cursor (x,y)=(%d,%d) want %v", st.CursorCol, st.CursorRow, v.Expect.Cursor))
		}
		if d := firstLineDiff("screen", v.Expect.Screen, modelLines(st.Lines)); d != "" {
			diffs = append(diffs, d)
		}
		if st.Alt && st.Parked != nil {
			if d := firstLineDiff("parked normal screen", v.Expect.NormalScreen, modelLines(st.Parked.Lines)); d != "" {
				diffs = append(diffs, d)
			}
		}
		if d := firstLineDiff("scrollback", v.Expect.Scrollback, modelLines(scroll)); d != "" {
			diffs = append(diffs, d)
		}
		if len(diffs) > 0 {
			failed++
			if failed <= 8 {
				t.Errorf("%s (%d ops): %s", v.Name, len(v.Ops), strings.Join(diffs, "; "))
			}
		}
	}
	if failed > 0 {
		t.Errorf("%d of %d vectors diverge from xterm", failed, len(vectors))
	}
}
